// Offline database restore. Exported files/reports are regenerated by the worker;
// device/CA keys must be protected in the separate host backup.
import Database from 'better-sqlite3';
import { readFileSync, copyFileSync, renameSync, chmodSync, existsSync, unlinkSync } from 'node:fs';
import { createReadStream } from 'node:fs';
import { createHash, randomUUID } from 'node:crypto';
import { Store } from '../server/store.js';

if (process.env.WG_OFFLINE_RESTORE !== 'services-stopped')
  throw new Error('Stopp alle fire tjenester. Sett WG_OFFLINE_RESTORE=services-stopped før gjenoppretting.');
const environment = process.env.WG_ENVIRONMENT,
  root = process.env.WG_DATA_ROOT,
  id = process.argv[2];
if (!root || !['production', 'development'].includes(environment) || !/^[0-9a-f-]{36}$/.test(id || ''))
  throw new Error('Oppgi WG_DATA_ROOT, WG_ENVIRONMENT og UUID fra sikkerhetskopilisten');
const paths = new Store({ root, environment, readonly: true });
paths.close();
const backup = paths.safe('system', 'backups', `${id}.sqlite3`),
  manifest = JSON.parse(readFileSync(paths.safe('system', 'backups', `${id}.json`), 'utf8'));
if (
  manifest.environment !== environment ||
  manifest.format !== 'wg-backup-1' ||
  manifest.state !== 'complete'
)
  throw new Error('Feil miljø eller ufullstendig sikkerhetskopi');
const sha = createHash('sha256');
for await (const chunk of createReadStream(backup)) sha.update(chunk);
if (sha.digest('hex') !== manifest.sha256) throw new Error('Sikkerhetskopiens SHA-256 stemmer ikke');
const source = new Database(backup, { readonly: true, fileMustExist: true });
try {
  if (
    source.pragma('integrity_check', { simple: true }) !== 'ok' ||
    source.prepare("SELECT value FROM meta WHERE key='environment'").get()?.value !== environment
  )
    throw new Error('Sikkerhetskopien bestod ikke integritetssjekken');
} finally {
  source.close();
}
const database = paths.safe('system', 'gateway.sqlite3'),
  before = paths.safe('system', 'backups', `before-restore-${Date.now()}.sqlite3`);
// Obtain a coherent safety copy and checkpoint the old database before replacing it.
const active = new Database(database, { fileMustExist: true, timeout: 2000 });
try {
  active.pragma('wal_checkpoint(TRUNCATE)');
  await active.backup(before);
} finally {
  active.close();
}
chmodSync(before, 0o600);
const temporary = `${database}.restore`;
copyFileSync(backup, temporary);
chmodSync(temporary, 0o640);
for (const suffix of ['-wal', '-shm']) if (existsSync(database + suffix)) unlinkSync(database + suffix);
renameSync(temporary, database);
const restored = new Store({ root, environment });
try {
  restored.db
    .transaction(() => {
      restored.db.exec('DELETE FROM sessions');
      for (const change of restored
        .changes()
        .filter((c) => ['draft', 'testing', 'confirming'].includes(c.state)))
        restored.rollback(change.id, 'backup_restored');
      restored.db.exec(
        "UPDATE commands SET state='cancelled' WHERE state IN ('queued','sent','received','testing')",
      );
      // Epoch milliseconds exceed command counters from an older snapshot and
      // prevent the device replay guard rejecting new commands after restore.
      restored.db
        .prepare("UPDATE meta SET value=MAX(CAST(value AS INTEGER),?) WHERE key='command_sequence'")
        .run(Date.now() * 1000);
      restored.db
        .prepare(
          "INSERT INTO meta VALUES ('projection_generation',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value",
        )
        .run(randomUUID());
      restored.audit('offline-restore', 'backup_restored', { id, sha256: manifest.sha256 });
    })
    .immediate();
} finally {
  restored.close();
}
console.log(
  `Gjenopprettet ${id} i ${environment}. Ny innlogging kreves. Kontroller enhetskonfigurasjon før normal drift.`,
);
